```cpp
#include "mainwindow.h"
#include "excelconverter.h"

#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QFileDialog>
#include <QMessageBox>
#include <QGroupBox>
#include <QThread>

MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , m_converter(nullptr)
{
    setupUI();
    setWindowTitle("Excel to CSV Converter");
    resize(600, 400);
}

MainWindow::~MainWindow()
{
    if (m_converter) {
        delete m_converter;
    }
}

void MainWindow::setupUI()
{
    QWidget *centralWidget = new QWidget(this);
    setCentralWidget(centralWidget);

    QVBoxLayout *mainLayout = new QVBoxLayout(centralWidget);

    // Directory selection group
    QGroupBox *directoryGroup = new QGroupBox("Select Directory", this);
    QHBoxLayout *directoryLayout = new QHBoxLayout(directoryGroup);

    m_directoryEdit = new QLineEdit(this);
    m_directoryEdit->setPlaceholderText("Select a directory containing Excel files...");
    m_directoryEdit->setReadOnly(true);

    m_browseButton = new QPushButton("Browse...", this);
    m_browseButton->setFixedWidth(100);

    directoryLayout->addWidget(m_directoryEdit);
    directoryLayout->addWidget(m_browseButton);

    // Convert button
    m_convertButton = new QPushButton("Convert Excel Files to CSV", this);
    m_convertButton->setEnabled(false);
    m_convertButton->setMinimumHeight(40);
    m_convertButton->setStyleSheet(
        "QPushButton {"
        "    background-color: #4CAF50;"
        "    color: white;"
        "    font-weight: bold;"
        "    border-radius: 5px;"
        "}"
        "QPushButton:hover {"
        "    background-color: #45a049;"
        "}"
        "QPushButton:disabled {"
        "    background-color: #cccccc;"
        "}"
    );

    // Progress bar
    m_progressBar = new QProgressBar(this);
    m_progressBar->setVisible(false);
    m_progressBar->setTextVisible(true);

    // Status label
    m_statusLabel = new QLabel("Ready", this);
    m_statusLabel->setStyleSheet("color: #666666;");

    // Log output group
    QGroupBox *logGroup = new QGroupBox("Conversion Log", this);
    QVBoxLayout *logLayout = new QVBoxLayout(logGroup);

    m_logOutput = new QTextEdit(this);
    m_logOutput->setReadOnly(true);
    m_logOutput->setStyleSheet(
        "QTextEdit {"
        "    background-color: #1e1e1e;"
        "    color: #d4d4d4;"
        "    font-family: 'Consolas', 'Monaco', monospace;"
        "    font-size: 10pt;"
        "}"
    );

    logLayout->addWidget(m_logOutput);

    // Add all to main layout
    mainLayout->addWidget(directoryGroup);
    mainLayout->addWidget(m_convertButton);
    mainLayout->addWidget(m_progressBar);
    mainLayout->addWidget(m_statusLabel);
    mainLayout->addWidget(logGroup, 1);

    // Connect signals
    connect(m_browseButton, &QPushButton::clicked, this, &MainWindow::onBrowseClicked);
    connect(m_convertButton, &QPushButton::clicked, this, &MainWindow::onConvertClicked);
}

void MainWindow::onBrowseClicked()
{
    QString directory = QFileDialog::getExistingDirectory(
        this,
        "Select Directory with Excel Files",
        QDir::homePath(),
        QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks
    );

    if (!directory.isEmpty()) {
        m_directoryEdit->setText(directory);
        m_convertButton->setEnabled(true);
        m_logOutput->clear();
        m_statusLabel->setText("Directory selected. Ready to convert.");
    }
}

void MainWindow::onConvertClicked()
{
    QString directory = m_directoryEdit->text();

    if (directory.isEmpty()) {
        QMessageBox::warning(this, "Warning", "Please select a directory first.");
        return;
    }

    // Create converter if needed
    if (m_converter) {
        delete m_converter;
    }
    m_converter = new ExcelConverter(this);

    // Connect converter signals
    connect(m_converter, &ExcelConverter::progress, 
            this, &MainWindow::onConversionProgress);
    connect(m_converter, &ExcelConverter::complete, 
            this, &MainWindow::onConversionComplete);
    connect(m_converter, &ExcelConverter::error, 
            this, &MainWindow::onConversionError);
    connect(m_converter, &ExcelConverter::logMessage, 
            this, &MainWindow::onLogMessage);

    m_logOutput->clear();
    setConvertingState(true);

    // Start conversion
    m_converter->convertDirectory(directory);
}

void MainWindow::onConversionProgress(int current, int total, const QString &fileName)
{
    m_progressBar->setMaximum(total);
    m_progressBar->setValue(current);
    m_statusLabel->setText(QString("Converting: %1 (%2/%3)").arg(fileName).arg(current).arg(total));
}

void MainWindow::onConversionComplete(int successCount, int failCount)
{
    setConvertingState(false);

    QString message = QString("Conversion complete!\n"
                              "Successfully converted: %1 files\n"
                              "Failed: %2 files")
                      .arg(successCount)
                      .arg(failCount);

    m_statusLabel->setText(QString("Complete: %1 successful, %2 failed")
                          .arg(successCount).arg(failCount));

    if (failCount == 0) {
        QMessageBox::information(this, "Success", message);
    } else {
        QMessageBox::warning(this, "Completed with Errors", message);
    }
}

void MainWindow::onConversionError(const QString &error)
{
    m_logOutput->append(QString("<span style='color: #ff6b6b;'>ERROR: %1</span>").arg(error));
}

void MainWindow::onLogMessage(const QString &message)
{
    m_logOutput->append(message);
}

void MainWindow::setConvertingState(bool converting)
{
    m_browseButton->setEnabled(!converting);
    m_convertButton->setEnabled(!converting);
    m_progressBar->setVisible(converting);

    if (converting) {
        m_progressBar->setValue(0);
    }
}
