```cpp
#include "excelconverter.h"

#include <QDir>
#include <QFileInfo>
#include <QFile>
#include <QTextStream>
#include <QDateTime>
#include <QCoreApplication>

// Include QXlsx headers
#include "xlsxdocument.h"
#include "xlsxworkbook.h"

ExcelConverter::ExcelConverter(QObject *parent)
    : QObject(parent)
{
}

ExcelConverter::~ExcelConverter()
{
}

void ExcelConverter::convertDirectory(const QString &directoryPath)
{
    emit logMessage(QString("Starting conversion in: %1").arg(directoryPath));
    emit logMessage("----------------------------------------");

    // Find all Excel files
    QStringList excelFiles = findExcelFiles(directoryPath);

    if (excelFiles.isEmpty()) {
        emit logMessage("<span style='color: #ffa500;'>No Excel files found in the directory.</span>");
        emit complete(0, 0);
        return;
    }

    emit logMessage(QString("Found %1 Excel file(s)").arg(excelFiles.size()));

    // Create output directory
    QString outputDir;
    if (!createOutputDirectory(directoryPath, outputDir)) {
        emit error("Failed to create output directory");
        emit complete(0, excelFiles.size());
        return;
    }

    emit logMessage(QString("Output directory: %1").arg(outputDir));
    emit logMessage("----------------------------------------");

    int successCount = 0;
    int failCount = 0;
    int total = excelFiles.size();

    for (int i = 0; i < excelFiles.size(); ++i) {
        QString filePath = excelFiles[i];
        QFileInfo fileInfo(filePath);
        QString fileName = fileInfo.fileName();

        emit progress(i + 1, total, fileName);
        emit logMessage(QString("Converting: %1").arg(fileName));

        if (convertExcelToCSV(filePath, outputDir)) {
            emit logMessage(QString("<span style='color: #90EE90;'>  ✓ Successfully converted</span>"));
            successCount++;
        } else {
            emit logMessage(QString("<span style='color: #ff6b6b;'>  ✗ Failed to convert</span>"));
            failCount++;
        }

        // Process events to keep UI responsive
        QCoreApplication::processEvents();
    }

    emit logMessage("----------------------------------------");
    emit logMessage(QString("Conversion complete: %1 successful, %2 failed")
                   .arg(successCount).arg(failCount));

    emit complete(successCount, failCount);
}

QStringList ExcelConverter::findExcelFiles(const QString &directoryPath)
{
    QStringList excelFiles;
    QDir dir(directoryPath);

    // Filter for Excel files (.xlsx, .xls, .xlsm)
    QStringList filters;
    filters << "*.xlsx" << "*.xls" << "*.xlsm";

    dir.setNameFilters(filters);
    dir.setFilter(QDir::Files | QDir::NoDotAndDotDot);

    QFileInfoList fileList = dir.entryInfoList();

    for (const QFileInfo &fileInfo : fileList) {
        // Skip temporary Excel files (start with ~$)
        if (!fileInfo.fileName().startsWith("~$")) {
            excelFiles.append(fileInfo.absoluteFilePath());
        }
    }

    return excelFiles;
}

bool ExcelConverter::createOutputDirectory(const QString &directoryPath, QString &outputPath)
{
    QDir dir(directoryPath);

    // Create a unique output folder name with timestamp
    QString timestamp = QDateTime::currentDateTime().toString("yyyyMMdd_HHmmss");
    QString folderName = QString("CSV_Output_%1").arg(timestamp);

    outputPath = dir.absoluteFilePath(folderName);

    if (!dir.mkpath(folderName)) {
        return false;
    }

    return true;
}

bool ExcelConverter::convertExcelToCSV(const QString &excelPath, const QString &outputDir)
{
    try {
        QXlsx::Document xlsx(excelPath);

        if (!xlsx.isLoadPackage()) {
            emit error(QString("Failed to load Excel file: %1").arg(excelPath));
            return false;
        }

        QFileInfo fileInfo(excelPath);
        QString baseName = fileInfo.completeBaseName();

        // Get all sheet names
        QStringList sheetNames = xlsx.sheetNames();

        if (sheetNames.isEmpty()) {
            emit error(QString("No sheets found in: %1").arg(excelPath));
            return false;
        }

        bool allSheetsConverted = true;

        for (const QString &sheetName : sheetNames) {
            xlsx.selectSheet(sheetName);

            // Determine output file name
            QString csvFileName;
            if (sheetNames.size() == 1) {
                csvFileName = QString("%1.csv").arg(baseName);
            } else {
                // Sanitize sheet name for file name
                QString sanitizedSheetName = sheetName;
                sanitizedSheetName.replace(QRegExp("[\\\\/:*?\"<>|]"), "_");
                csvFileName = QString("%1_%2.csv").arg(baseName).arg(sanitizedSheetName);
            }

            QString csvPath = QDir(outputDir).absoluteFilePath(csvFileName);

            QFile csvFile(csvPath);
            if (!csvFile.open(QIODevice::WriteOnly | QIODevice::Text)) {
                emit error(QString("Failed to create CSV file: %1").arg(csvPath));
                allSheetsConverted = false;
                continue;
            }

            QTextStream out(&csvFile);
            out.setCodec("UTF-8");

            // Get the dimensions of the used range
            QXlsx::CellRange range = xlsx.dimension();

            if (!range.isValid()) {
                emit logMessage(QString("  Sheet '%1' is empty, skipping").arg(sheetName));
                csvFile.close();
                continue;
            }

            int firstRow = range.firstRow();
            int lastRow = range.lastRow();
            int firstCol = range.firstColumn();
            int lastCol = range.lastColumn();

            // Write data to CSV
            for (int row = firstRow; row <= lastRow; ++row) {
                QStringList rowData;

                for (int col = firstCol; col <= lastCol; ++col) {
                    QXlsx::Cell *cell = xlsx.cellAt(row, col);
                    QString cellValue;

                    if (cell) {
                        QVariant value = cell->value();

                        // Handle different data types
                        if (value.type() == QVariant::DateTime) {
                            cellValue = value.toDateTime().toString(Qt::ISODate);
                        } else if (value.type() == QVariant::Date) {
                            cellValue = value.toDate().toString(Qt::ISODate);
                        } else if (value.type() == QVariant::Time) {
                            cellValue = value.toTime().toString(Qt::ISODate);
                        } else if (value.type() == QVariant::Double) {
                            // Preserve decimal precision
                            cellValue = QString::number(value.toDouble(), 'g', 15);
                        } else {
                            cellValue = value.toString();
                        }
                    }

                    rowData.append(escapeCSVField(cellValue));
                }

                out << rowData.join(",") << "\n";
            }

            csvFile.close();

            if (sheetNames.size() > 1) {
                emit logMessage(QString("  Sheet '%1' -> %2").arg(sheetName).arg(csvFileName));
            }
        }

        return allSheetsConverted;

